<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $proyectos = Illuminate\Support\Facades\DB::table("proyectos")->where("ejercicio_id", 2026)->where("nombre", "like", "%Representación del Tribunal en los distintos eventos%")->get(); foreach($proyectos as $p) { echo "Proyecto: $p->proyecto_id\n"; $acciones = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->where("proyecto_id", $p->proyecto_id)->get(); foreach($acciones as $a) { echo "  Accion ID: $a->accion_sustantiva_id, Text: $a->descripcion, Num: $a->numero\n"; } }
